import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Bqn-bhhR.js";const u=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/core-concepts.md","filePath":"guide/core-concepts.md","lastUpdated":1786047222000}'),d={name:"guide/core-concepts.md"};function s(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><p>Codemark revolves around a few primitives designed to make code navigation and context-sharing durable.</p><h2 id="bookmarks" tabindex="-1">Bookmarks <a class="header-anchor" href="#bookmarks" aria-label="Permalink to &quot;Bookmarks&quot;">​</a></h2><p>A <strong>bookmark</strong> is not a line number. It&#39;s a semantic anchor: a tree-sitter query that identifies code by its position in the Abstract Syntax Tree (a function, a type, a block), plus a normalized content hash for fallback matching.</p><p>Because it tracks <em>structure</em>, adding lines above the bookmark or refactoring the surrounding code doesn&#39;t lose your place — Codemark re-runs the query against the current tree and finds the node again. This is <strong>Smart Resolution</strong>, the tiered matcher covered in <a href="./health-status">Health Status</a>.</p><p>Every bookmark carries:</p><ul><li>The <strong>query</strong> — the durable identity, generated once at creation.</li><li>A <strong>content hash</strong> — <code>sha256:</code> over whitespace-normalized text, for drift recovery.</li><li><strong>Annotations</strong> — append-only notes and comments with provenance (author, timestamp, source).</li><li><strong>Tags</strong> — a structured, colon-prefixed taxonomy (<code>feature:auth</code>, <code>layer:api</code>, <code>role:entrypoint</code>).</li><li><strong>Health</strong> — <code>active</code>, <code>drifted</code>, <code>stale</code>, or <code>archived</code>.</li><li><strong>Git context</strong> — commit, branch, and breadcrumbs up the enclosing structure.</li></ul><h2 id="collections" tabindex="-1">Collections <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;Collections&quot;">​</a></h2><p>A <strong>collection</strong> (also called a <em>tour</em>) is an ordered grouping of bookmarks — think of it as a playlist or a guided tour of a specific flow in your codebase.</p><p>For example, a <code>request-lifecycle</code> collection might hold:</p><ol><li>The API route handler</li><li>The authentication middleware</li><li>The service layer</li><li>The query builder</li></ol><p>Collections have their own metadata: a description, tags, links (PRs, issues, docs), and a rolled-up health (the worst of their bookmarks). Publish and pull them across a team with the <code>codetours</code> sync server.</p><h2 id="tours" tabindex="-1">Tours <a class="header-anchor" href="#tours" aria-label="Permalink to &quot;Tours&quot;">​</a></h2><p>A <strong>tour</strong> is the shareable, publishable form of a collection — the same ordered bookmarks, packaged for syncing to a remote server with <code>P</code> (push) / <code>p</code> (pull) in the TUI. In the CLI, <code>codemark tour</code> commands manage them.</p><h2 id="repositories-identity" tabindex="-1">Repositories &amp; identity <a class="header-anchor" href="#repositories-identity" aria-label="Permalink to &quot;Repositories &amp; identity&quot;">​</a></h2><p>Codemark is <strong>Git-aware</strong>. It detects your repository automatically (walking up from the working directory) and tracks bookmarks by a durable identity derived from the Git remote (<code>owner/name</code>), not just the path on disk. This is what enables multi-repo queries and lets a moved repo be recognized. See <a href="./repository-registry">Repository Registry</a>.</p><h2 id="worktrees" tabindex="-1">Worktrees <a class="header-anchor" href="#worktrees" aria-label="Permalink to &quot;Worktrees&quot;">​</a></h2><p>Git worktrees share the main repo&#39;s <code>.git</code>, so Codemark resolves every worktree to the same repo root and the same <code>.codemark/codemark.db</code>. Your bookmarks are accessible from any worktree of the same repository — no duplication, no setup.</p><h2 id="notes-vs-comments" tabindex="-1">Notes vs. comments <a class="header-anchor" href="#notes-vs-comments" aria-label="Permalink to &quot;Notes vs. comments&quot;">​</a></h2><p>Two distinct, durable-vs-ephemeral channels on every bookmark:</p><ul><li><strong>Notes</strong> (<code>--note</code>) — durable, plain-prose explanations of <em>what the code is and why it matters</em>. Context-independent and reusable across any session.</li><li><strong>Comments</strong> (<code>--comment</code>) — markdown discussion tied to a <em>task, ticket, or debugging session</em>. Ephemeral and session-scoped.</li></ul><p>Keeping them separate prevents task-specific chatter from polluting the durable explanations an agent loads for context.</p><h2 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h2><p>Use structured, colon-prefixed tags for precise filtering. Apply multiple when creating a bookmark; filter by one at a time with <code>--tag</code>:</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>feature:</code></td><td><code>feature:auth</code></td><td>Feature or domain</td></tr><tr><td><code>layer:</code></td><td><code>layer:api</code></td><td>Architectural layer</td></tr><tr><td><code>role:</code></td><td><code>role:entrypoint</code></td><td>Responsibility</td></tr><tr><td><code>type:</code></td><td><code>type:function</code></td><td>Code-element kind</td></tr><tr><td><code>task:</code></td><td><code>task:fix-123</code></td><td>Work item</td></tr><tr><td><code>pr:</code> / <code>issue:</code></td><td><code>pr:116</code></td><td>Associated PR/issue</td></tr><tr><td><code>security:</code></td><td><code>security:auth</code></td><td>Security-sensitive code</td></tr><tr><td><code>module:</code> / <code>crate:</code> / <code>package:</code></td><td><code>crate:auth</code></td><td>Module/package context</td></tr></tbody></table><p>See the <a href="./agent-skills">Agent Skill</a> page for the full taxonomy and per-language module conventions.</p>',26)])])}const m=t(d,[["render",s]]);export{u as __pageData,m as default};
